#!/usr/bin/env node
/**
 * Deterministically compiles the committed MEXT registry CSV into a typed TS module.
 *
 *   data/japan-universities-registry-2026-provisional/master_registry.csv
 *     -> src/lib/data/universities/registry.generated.ts
 *
 * Identity fields only. Values MEXT records as `not_found` become `null` (never
 * invented). Enrichment (JLPT/EJU, tuition, programs, careers) is intentionally NOT
 * emitted here — it does not exist in the source — and is attached as explicit
 * "not verified" gaps at load time in index.ts.
 *
 * The generated file is a build artifact: do not hand-edit it; re-run this script.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..');
const SRC_CSV = join(
  ROOT,
  'data/japan-universities-registry-2026-provisional/master_registry.csv',
);
const OUT_TS = join(ROOT, 'src/lib/data/universities/registry.generated.ts');

// Values MEXT uses to mean "absent from the canonical file".
const ABSENT = new Set(['not_found', 'not_applicable', 'not_published', '']);

/** Minimal RFC4180 parser: handles quoted fields, escaped quotes, embedded commas/newlines. */
function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  const s = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  for (let i = 0; i < s.length; i += 1) {
    const c = s[i];
    if (inQuotes) {
      if (c === '"') {
        if (s[i + 1] === '"') {
          field += '"';
          i += 1;
        } else {
          inQuotes = false;
        }
      } else {
        field += c;
      }
    } else if (c === '"') {
      inQuotes = true;
    } else if (c === ',') {
      row.push(field);
      field = '';
    } else if (c === '\n') {
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
    } else {
      field += c;
    }
  }
  // trailing field / row (no final newline)
  if (field !== '' || row.length > 0) {
    row.push(field);
    rows.push(row);
  }
  return rows;
}

function absentToNull(v) {
  const t = (v ?? '').trim();
  return ABSENT.has(t) ? null : t;
}

const raw = readFileSync(SRC_CSV, 'utf8');
const rows = parseCsv(raw);
const header = rows[0];
const idx = Object.fromEntries(header.map((h, i) => [h, i]));

const required = [
  'university_id',
  'mext_school_code',
  'official_name_ja',
  'normalized_name_ja',
  'establishment_category',
  'institution_status',
  'prefecture_code',
  'prefecture_ja',
  'municipality_ja',
  'address_ja',
  'postal_code',
];
for (const col of required) {
  if (!(col in idx)) throw new Error(`master_registry.csv missing required column: ${col}`);
}

const SECTORS = new Set(['national', 'public', 'private']);
const records = [];
for (let r = 1; r < rows.length; r += 1) {
  const row = rows[r];
  if (!row || row.length === 1 && row[0] === '') continue;
  if ((row[idx.institution_status] ?? '').trim() !== 'active') continue;

  const sector = (row[idx.establishment_category] ?? '').trim();
  if (!SECTORS.has(sector)) {
    throw new Error(`Unexpected establishment_category "${sector}" at row ${r + 1}`);
  }

  records.push({
    id: (row[idx.university_id] ?? '').trim(),
    mextSchoolCode: (row[idx.mext_school_code] ?? '').trim(),
    nameJa: (row[idx.official_name_ja] ?? '').trim(),
    nameEn: absentToNull(row[idx.official_name_en]),
    normalizedNameJa: (row[idx.normalized_name_ja] ?? '').trim(),
    sector,
    prefectureCode: (row[idx.prefecture_code] ?? '').trim(),
    prefectureJa: (row[idx.prefecture_ja] ?? '').trim(),
    municipalityJa: (row[idx.municipality_ja] ?? '').trim(),
    addressJa: (row[idx.address_ja] ?? '').trim(),
    postalCode: (row[idx.postal_code] ?? '').trim(),
    officialWebsiteUrl: absentToNull(row[idx.official_website_url]),
  });
}

// Deterministic order: by MEXT school code.
records.sort((a, b) => a.mextSchoolCode.localeCompare(b.mextSchoolCode));

// Dates come from the source file / manifest (stable, not "now").
const releaseDate = '2026-05-01';
const retrievedAt = '2026-05-29';

const banner = `// AUTO-GENERATED by scripts/build-university-registry.mjs — DO NOT EDIT.
// Source: MEXT 2026-05-01 provisional F1 (大学) school-code registry.
// See data/japan-universities-registry-2026-provisional/MANIFEST.md for provenance.
// Identity fields only. \`null\` means the value is absent from the canonical MEXT file
// (never invented). Admissions/cost/program/career data is intentionally absent and is
// attached as explicit "not verified" gaps at load time.
`;

const body = `${banner}
export interface RawUniversityRecord {
  id: string;
  mextSchoolCode: string;
  nameJa: string;
  /** null when absent from the canonical MEXT file — never invented. */
  nameEn: string | null;
  normalizedNameJa: string;
  sector: 'national' | 'public' | 'private';
  prefectureCode: string;
  prefectureJa: string;
  municipalityJa: string;
  addressJa: string;
  postalCode: string;
  /** null when absent from the canonical MEXT file — never inferred. */
  officialWebsiteUrl: string | null;
}

export const REGISTRY_RELEASE_DATE = ${JSON.stringify(releaseDate)};
export const REGISTRY_RETRIEVED_AT = ${JSON.stringify(retrievedAt)};

export const RAW_UNIVERSITY_RECORDS: RawUniversityRecord[] = ${JSON.stringify(records, null, 2)};
`;

writeFileSync(OUT_TS, body, 'utf8');
console.log(
  `Generated ${OUT_TS} with ${records.length} active universities ` +
    `(national/public/private: ${records.filter((x) => x.sector === 'national').length}/` +
    `${records.filter((x) => x.sector === 'public').length}/` +
    `${records.filter((x) => x.sector === 'private').length}).`,
);
